-- W3.3b (DR-078): treats / symptom_of / is_a edges checked against international sources
-- Two reviewers judged 293 active edges; a third opened every cited link (search pages, dead
-- links and wrong papers replaced or rejected). Decision files: tmp/edges-*-2026-10-22.json.
--   verify  164  correct as stored; evidence_verified_* stamped, source + evidence in edge_note
--   change   29  correct after a type change and/or swapped direction (e.g. "caries symptom_of
--                abscess" -> caries causes abscess); stamped as verified. If the corrected edge
--                already exists, this one is deprecated instead (no duplicates).
--   wrong    15  clinically false -> status 'deprecated' (never deleted), reason in edge_note.
--                Includes apicoectomy treats peri-implantitis, implant failure..., Neodent is_a
--                Straumann implant. Awake/pediatric/stress bruxism were is_a sleep bruxism; they
--                get is_a bruxism instead (2018 international consensus) and their parent is fixed.
--   flag     85  no source found or needs a clinician -> status 'flagged_review' (brand MD review)
-- medical_reviewer_signoff_* is not touched: an agent-verified edge is not a clinician sign-off.

begin;

create temp table _d(id uuid primary key, act text, new_type text, swap boolean, kind text, note text) on commit drop;
