-- guard: every edge still exists and is active
do $g$ declare n int; begin
  select count(*) into n from _d d left join seo_entity_relationships r on r.id = d.id where r.id is null or r.status <> 'active';
  if n > 0 then raise exception 'W3.3b abort: % edges missing or no longer active', n; end if;
end $g$;

create table public.bak_w33b_20261022 as
  select r.* from seo_entity_relationships r where r.id in (select id from _d);
alter table public.bak_w33b_20261022 enable row level security;

-- 1. wrong -> deprecated
update seo_entity_relationships r
set status = 'deprecated', updated_at = now(),
    edge_note = concat_ws(E'\n', r.edge_note, '[W3.3 2026-10-22] deprecated — clinically false: ' || d.note)
from _d d where d.id = r.id and d.act = 'wrong';

-- 1b. awake / pediatric / stress bruxism belong under bruxism, not sleep bruxism
insert into seo_entity_relationships (from_entity_fp, to_entity_fp, edge_type, edge_note, status, load_source,
                                      evidence_verified_at, evidence_verified_by)
select c.fp, 'bruxism', 'is_a',
       '[W3.3 2026-10-22] replaces is_a sleep-bruxism — Lobbezoo et al. 2018 international consensus: sleep and awake bruxism are distinct forms of bruxism (PMID 29926505)',
       'active', 'w33_edge_review', now(), 'agent:pubmed'
from (values ('awake-bruxism'), ('pediatric-bruxism'), ('stress-bruxism')) c(fp)
where not exists (select 1 from seo_entity_relationships r where r.from_entity_fp = c.fp and r.to_entity_fp = 'bruxism' and r.edge_type = 'is_a');
update seo_entity_graph set parent_entity_fp = 'bruxism', last_graph_update = now()
where entity_fingerprint in ('awake-bruxism', 'pediatric-bruxism', 'stress-bruxism') and parent_entity_fp = 'sleep-bruxism';

-- 2. no source / needs a clinician -> flagged_review
update seo_entity_relationships r
set status = 'flagged_review', updated_at = now(),
    edge_note = concat_ws(E'\n', r.edge_note, '[W3.3 2026-10-22] flagged: ' || d.note)
from _d d where d.id = r.id and d.act = 'flag';

-- 3. type / direction changes (deprecate instead when the corrected edge already exists)
create temp table _t on commit drop as
select d.id,
       case when d.swap then r.to_entity_fp else r.from_entity_fp end as nf,
       case when d.swap then r.from_entity_fp else r.to_entity_fp end as nt,
       coalesce(d.new_type, r.edge_type) as ntype, r.edge_type as old_type, r.from_entity_fp as of, r.to_entity_fp as ot
from _d d join seo_entity_relationships r on r.id = d.id where d.act = 'change';
create temp table _t2 on commit drop as
select t.*, row_number() over (partition by nf, nt, ntype order by id) as rn,
       exists (select 1 from seo_entity_relationships q
               where q.from_entity_fp = t.nf and q.to_entity_fp = t.nt and q.edge_type = t.ntype
                 and q.status = 'active' and q.id not in (select id from _t)) as clash
from _t t;
update seo_entity_relationships r
set status = 'deprecated', updated_at = now(),
    edge_note = concat_ws(E'\n', r.edge_note, '[W3.3 2026-10-22] deprecated — corrected form (' || t.nf || ' ' || t.ntype || ' ' || t.nt || ') already exists')
from _t2 t where t.id = r.id and (t.clash or t.rn > 1);
update seo_entity_relationships r
set from_entity_fp = t.nf, to_entity_fp = t.nt, edge_type = t.ntype, updated_at = now(),
    edge_note = concat_ws(E'\n', r.edge_note, '[W3.3 2026-10-22] was ' || t.of || ' ' || t.old_type || ' ' || t.ot)
from _t2 t where t.id = r.id and not t.clash and t.rn = 1;

-- 4. stamp verified + corrected edges that are still active
update seo_entity_relationships r
set evidence_verified_at = now(), evidence_verified_by = 'agent:' || coalesce(d.kind, 'review'), updated_at = now(),
    edge_note = concat_ws(E'\n', r.edge_note, '[W3.3 2026-10-22] verified: ' || d.note)
from _d d where d.id = r.id and d.act in ('verify', 'change') and r.status = 'active';

commit;
